mapper.sql:
where user_id = #{userId}
  and del_flag = '0'

    and title like concat('%', #{filter.title}, '%')


    and process_id = #{filter.processId}


    and process_name like concat('%', #{filter.processName}, '%')


    and originator_name like concat('%', #{filter.originatorName}, '%')


    and instance_id = #{filter.instanceId}


    and task_id = #{filter.taskId}


    and category_id = #{filter.categoryId}


    and deployment_id = #{filter.deploymentId}

mapper.select:
select count(*)
from wf_copy
where instance_id = #{instanceId}
  and user_id = #{userId}
  and del_flag = '0'
